{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.warehouse_availability_mix AS WITH alloc_ref_dates AS ( SELECT DISTINCT order_date, DATEADD(\'day\', -1, order_date) AS reference_date FROM snitch_db.maplemonk.fresh_actual_allocation ), wh_daily AS ( SELECT ar.order_date, w.SNAPSHOT_DATE, CASE WHEN UPPER(w.FACILITY) LIKE \'%NORTH%\' OR UPPER(w.FACILITY) LIKE \'%TAURU%\' THEN \'NORTH\' WHEN UPPER(w.FACILITY) LIKE \'%WH1%\' OR UPPER(w.FACILITY) LIKE \'%WH2%\' THEN \'SOUTH\' ELSE \'SOUTH\' END AS wh_zone, UPPER(SUBSTRING(w.ITEM_SKUCODE, 1, LENGTH(w.ITEM_SKUCODE) - LENGTH(SPLIT_PART(w.ITEM_SKUCODE, \'-\', -1)) - 1)) AS sku_group, UPPER(SPLIT_PART(w.ITEM_SKUCODE, \'-\', -1)) AS size_code, COALESCE(w.INVENTORY, 0) AS usable_qty FROM alloc_ref_dates ar INNER JOIN snitch_db.maplemonk.WH_CLOSING_INV_DAILY_BASE w ON w.SNAPSHOT_DATE = ar.reference_date ), wh_pivot AS ( SELECT order_date, wh_zone, sku_group, SUM(CASE WHEN size_code IN (\'S\', \'28\', \'30\') THEN usable_qty ELSE 0 END) AS s_units, SUM(CASE WHEN size_code IN (\'M\', \'30\', \'32\') THEN usable_qty ELSE 0 END) AS m_units, SUM(CASE WHEN size_code IN (\'L\', \'32\', \'34\') THEN usable_qty ELSE 0 END) AS l_units, SUM(CASE WHEN size_code IN (\'XL\', \'34\', \'36\') THEN usable_qty ELSE 0 END) AS xl_units, SUM(CASE WHEN size_code IN (\'3XL\', \'38\', \'40\') THEN usable_qty ELSE 0 END) AS xl3_units, SUM(CASE WHEN size_code IN (\'4XL\', \'40\', \'42\') THEN usable_qty ELSE 0 END) AS xl4_units, SUM(CASE WHEN size_code IN (\'5XL\', \'42\', \'44\') THEN usable_qty ELSE 0 END) AS xl5_units, SUM(CASE WHEN size_code IN (\'6XL\', \'44\', \'46\') THEN usable_qty ELSE 0 END) AS xl6_units FROM wh_daily GROUP BY 1,2,3 ), wh_options AS ( SELECT order_date, wh_zone, sku_group, CASE WHEN sku_group LIKE \'4MBG%\' OR sku_group LIKE \'4BRN%\' OR sku_group LIKE \'4BPL%\' OR sku_group LIKE \'4BTR%\' OR sku_group LIKE \'4BCH%\' OR sku_group LIKE \'4BJE%\' OR sku_group LIKE \'4BJK%\' OR sku_group LIKE \'4BSW%\' OR sku_group LIKE \'4BHD%\' OR sku_group LIKE \'4BOS%\' OR sku_group LIKE \'4BSHS%\' OR sku_group LIKE \'4BSFS%\' OR sku_group LIKE \'4BSH%\' OR sku_group LIKE \'4BBL%\' OR sku_group LIKE \'4BCA%\' OR sku_group LIKE \'4BSWT%\' OR sku_group LIKE \'4BCD%\' OR sku_group LIKE \'4BJO%\' THEN GREATEST(LEAST( ROUND((xl3_units - 1) / 3), ROUND((xl4_units - 1) / 3), ROUND((xl5_units - 1) / 2), ROUND((xl6_units - 1) / 2) ), 0) ELSE GREATEST(LEAST( ROUND((s_units - 1) / 3), ROUND((m_units - 1) / 4), ROUND((l_units - 1) / 4), ROUND((xl_units - 1) / 3) ), 0) END AS full_size_options FROM wh_pivot ), wh_zoned AS ( SELECT order_date, wh_zone, sku_group FROM wh_options WHERE full_size_options >= 1 ), wh_tagged AS ( SELECT w.order_date, w.wh_zone, ms.category, COALESCE(UPPER(ms.style), \'SNITCH\') AS style, COALESCE(UPPER(ms.meta1), \'N/A\') AS meta1, COALESCE(UPPER(ms.meta2), \'N/A\') AS meta2, COALESCE(UPPER(ms.meta3), \'N/A\') AS meta3, COUNT(DISTINCT w.sku_group) AS wh_option_count FROM wh_zoned w LEFT JOIN snitch_db.maplemonk.metafields_std ms ON UPPER(w.sku_group) = UPPER(ms.sku_group) WHERE ms.category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), zone_specific AS ( SELECT order_date, wh_zone AS scope, category, style, meta1, meta2, meta3, wh_option_count, wh_option_count / NULLIF(SUM(wh_option_count) OVER (PARTITION BY order_date, wh_zone), 0) AS warehouse_mix_pct FROM wh_tagged ), company_wide AS ( SELECT order_date, \'ALL\' AS scope, category, style, meta1, meta2, meta3, SUM(wh_option_count) AS wh_option_count, SUM(wh_option_count) / NULLIF(SUM(SUM(wh_option_count)) OVER (PARTITION BY order_date), 0) AS warehouse_mix_pct FROM wh_tagged GROUP BY order_date, category, style, meta1, meta2, meta3 ) SELECT * FROM zone_specific UNION ALL SELECT * FROM company_wide;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            